    visited.add(start)

    while stack:
        node = stack.pop()
        if node in adj:
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    # Return sorted list of reachable vertices
    return sorted(list(visited))
